    # Since d >= 2, 4(a^2+b^2) <= limit_max_m.
    # Since a >= 1, b >= 2, a^2+b^2 >= 5.

    # Let's iterate d from 2 upwards.
    d = 2
    while True:
        d_sq = d * d
        if d_sq > limit_max_m:
            break

        max_sum_sq = limit_max_m // d_sq

        # Iterate a from 1
        a = 1
        while True:
            a_sq = a * a
            if a_sq >= max_sum_sq:
