import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def find_good_numbers(n=100):
    good_numbers = set()
    # Iterate over x > y > 0 up to n
    for x in range(1, n + 1):
        for y in range(1, x):
            if gcd(x, y) == 1:
                m = x**2 + y**2
                good_numbers.add(m)

    sorted_good_numbers = sorted(list(good_numbers))
    return sorted_good_numbers

